INSERT IGNORE INTO `#__j2commerce_invoicetemplates` (`j2commerce_invoicetemplate_id`, `title`, `invoice_type`, `orderstatus_id`, `group_id`, `paymentmethod`, `body`, `body_json`, `body_source`, `body_source_file`, `custom_css`, `language`, `enabled`, `ordering`)
VALUES  (1, 'Packing Slip', 'packingslip', '*', '1', '*', '<!-- J2Commerce Packing Slip — Modern Template -->\n<style>\n  @media only screen and (max-width: 620px) {\n    .slip-container { width: 100% !important; }\n    .mobile-padding { padding-left: 16px !important; padding-right: 16px !important; }\n    .mobile-full { width: 100% !important; display: block !important; }\n    .address-col { display: block !important; width: 100% !important; padding: 0 0 12px 0 !important; }\n    .item-img { width: 40px !important; height: 40px !important; }\n  }\n  @media print {\n    body { margin: 0; padding: 0; }\n    .no-print { display: none !important; }\n  }\n</style>\n\n<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 20px 10px;">\n      <table class="slip-container" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%; background-color: #ffffff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td style="padding: 20px 30px; background-color: #ffffff; border-radius: 12px 12px 0 0; text-align: center;">\n            [IF:STORE_LOGO_URL]\n            <img src="[STORE_LOGO_URL]" alt="[SITENAME]" style="display: block; margin: 0 auto; border: 0; height: [LOGO_MAX_HEIGHT]px; width: auto;" />\n            [/IF:STORE_LOGO_URL]\n            [IFNOT:STORE_LOGO_URL]\n            <span style="font-size: 22px; font-weight: bold; color: [ACCENT_COLOR];">[SITENAME]</span>\n            [/IFNOT:STORE_LOGO_URL]\n          </td>\n        </tr>\n\n        <!-- Packing Slip Header Banner -->\n        <tr>\n          <td style="background-color: [ACCENT_COLOR]; padding: 28px 30px; text-align: center;">\n            <!-- Box Icon -->\n            <table cellpadding="0" cellspacing="0" border="0" align="center">\n              <tr>\n                <td style="width: 50px; height: 50px; background-color: rgba(255,255,255,0.2); border-radius: 50%; text-align: center; vertical-align: middle; font-size: 24px; color: #ffffff;">\n                  &#128230;\n                </td>\n              </tr>\n            </table>\n            <h1 style="margin: 14px 0 4px 0; font-size: 24px; font-weight: bold; color: #ffffff; text-transform: uppercase; letter-spacing: 1px;">[LANG:COM_J2COMMERCE_EMAIL_PACKING_SLIP]</h1>\n            <p style="margin: 0; font-size: 14px; color: rgba(255,255,255,0.85);">\n              [LANG:COM_J2COMMERCE_EMAIL_ORDER_5]\n            </p>\n          </td>\n        </tr>\n\n        <!-- Ship To & Order Info Cards -->\n        <tr>\n          <td class="mobile-padding" style="padding: 20px 20px 0 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0">\n              <tr>\n                <!-- Ship To -->\n                <!--[IF:SHIPPING_FIRSTNAME]-->\n                <td class="address-col" style="width: 60%; vertical-align: top; padding-right: 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_SHIP_TO]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 14px; color: #1f2937; line-height: 1.6;">\n                        <strong style="font-size: 15px;">[SHIPPING_FIRSTNAME] [SHIPPING_LASTNAME]</strong>\n                        [IF:SHIPPING_COMPANY]<br />[SHIPPING_COMPANY][/IF:SHIPPING_COMPANY]<br />\n                        [SHIPPING_ADDRESS_1]\n                        [IF:SHIPPING_ADDRESS_2]<br />[SHIPPING_ADDRESS_2][/IF:SHIPPING_ADDRESS_2]<br />\n                        [SHIPPING_CITY], [SHIPPING_STATE] [SHIPPING_ZIP]<br />\n                        [SHIPPING_COUNTRY]\n                        [IF:SHIPPING_PHONE]<br />&#128222; [SHIPPING_PHONE][/IF:SHIPPING_PHONE]\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n                <!--[/IF:SHIPPING_FIRSTNAME]-->\n                <!-- Order Details -->\n                <td class="address-col" style="width: 40%; vertical-align: top; padding-left: 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_ORDER_DETAILS]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 13px; color: #1f2937; line-height: 1.8;">\n                        <strong>[LANG:COM_J2COMMERCE_EMAIL_ORDER_3]:</strong> #[ORDERID]<br />\n                        <strong>[LANG:COM_J2COMMERCE_EMAIL_DATE]:</strong> [ORDERDATE]<br />\n                        <strong>[LANG:COM_J2COMMERCE_EMAIL_STATUS]:</strong> [ORDERSTATUS]\n                        [IF:SHIPPING_METHOD]<br /><strong>[LANG:COM_J2COMMERCE_EMAIL_SHIP_VIA]:</strong> [SHIPPING_METHOD][/IF:SHIPPING_METHOD]\n                        [IF:SHIPPING_TRACKING_ID]<br /><strong>[LANG:COM_J2COMMERCE_EMAIL_TRACKING]:</strong> [SHIPPING_TRACKING_ID][/IF:SHIPPING_TRACKING_ID]\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Items Card (NO PRICES) -->\n        <tr>\n          <td class="mobile-padding" style="padding: 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; overflow: hidden;">\n              <!-- Card Header -->\n              <tr>\n                <td colspan="4" style="padding: 16px 20px; border-bottom: 1px solid #f3f4f6;">\n                  <span style="font-size: 15px; font-weight: bold; color: #1f2937;">[LANG:COM_J2COMMERCE_EMAIL_ITEMS_TO_PACK]</span>\n                </td>\n              </tr>\n              <!-- Column Headers -->\n              <tr>\n                <td style="padding: 10px 20px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px;" colspan="2">[LANG:COM_J2COMMERCE_EMAIL_PRODUCT]</td>\n                <td style="padding: 10px 10px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; text-align: center; width: 50px;">[LANG:COM_J2COMMERCE_EMAIL_QTY]</td>\n                <td style="padding: 10px 20px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; text-align: center; width: 70px;">[LANG:COM_J2COMMERCE_EMAIL_PACKED]</td>\n              </tr>\n              <!-- Items -->\n              <!--[ITEMS_LOOP]-->\n              <tr>\n                <td style="padding: 12px 0 12px 20px; border-top: 1px solid #f3f4f6; vertical-align: top; width: 60px;">\n                  [IF:ITEM_IMAGE]\n                  <img src="[ITEM_IMAGE]" alt="[ITEM_NAME]" width="50" height="50" class="item-img" style="border-radius: 6px; object-fit: cover; display: block; border: 1px solid #f3f4f6;" />\n                  [/IF:ITEM_IMAGE]\n                  [IFNOT:ITEM_IMAGE]\n                  <table cellpadding="0" cellspacing="0" border="0"><tr><td style="width: 50px; height: 50px; background-color: #f3f4f6; border-radius: 6px; text-align: center; vertical-align: middle; font-size: 20px; color: #d1d5db;">&#128230;</td></tr></table>\n                  [/IFNOT:ITEM_IMAGE]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; vertical-align: top;">\n                  <span style="font-size: 14px; font-weight: 600; color: #1f2937;">[ITEM_NAME]</span>\n                  [IF:ITEM_SKU]<br /><span style="font-size: 12px; color: #9ca3af;">[LANG:COM_J2COMMERCE_EMAIL_SKU_2]</span>[/IF:ITEM_SKU]\n                  [IF:ITEM_OPTIONS]<br /><span style="font-size: 12px; color: #6b7280;">[ITEM_OPTIONS]</span>[/IF:ITEM_OPTIONS]\n                  [IF:ITEM_WEIGHT]<br /><span style="font-size: 12px; color: #9ca3af;">[LANG:COM_J2COMMERCE_EMAIL_WEIGHT]</span>[/IF:ITEM_WEIGHT]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; text-align: center; vertical-align: top; font-size: 18px; font-weight: bold; color: #1f2937;">[ITEM_QTY]</td>\n                <td style="padding: 12px 20px; border-top: 1px solid #f3f4f6; text-align: center; vertical-align: top;">\n                  <!-- Checkbox placeholder for warehouse staff -->\n                  <table cellpadding="0" cellspacing="0" border="0" align="center"><tr><td style="width: 24px; height: 24px; border: 2px solid #d1d5db; border-radius: 4px; background-color: #ffffff;"></td></tr></table>\n                </td>\n              </tr>\n              <!--[/ITEMS_LOOP]-->\n              <!-- Total Items Count -->\n              <tr>\n                <td colspan="4" style="padding: 14px 20px; background-color: #f9fafb; border-top: 1px solid #e5e7eb;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td style="font-size: 13px; font-weight: bold; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_TOTAL_WEIGHT]</td>\n                      <td style="font-size: 13px; font-weight: bold; color: #1f2937; text-align: right;">[SHIPPING_TOTAL_WEIGHT]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Customer Note -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0;">\n            [IF:CUSTOMER_NOTE]\n            <table width="100%" cellpadding="0" cellspacing="0" border="0">\n              <tr>\n                <td style="padding: 0 20px 16px 20px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 13px; font-weight: bold; color: #92400e; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_CUSTOMER_NOTE_2]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 0 18px 14px 18px; font-size: 14px; color: #78350f; line-height: 1.5;">[CUSTOMER_NOTE]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n            [/IF:CUSTOMER_NOTE]\n          </td>\n        </tr>\n\n        <!-- Packed By / Signature Section -->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 20px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f9fafb; border: 1px solid #e5e7eb; border-radius: 10px;">\n              <tr>\n                <td style="padding: 14px 18px; border-bottom: 1px solid #e5e7eb; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_FULFILLMENT]</td>\n              </tr>\n              <tr>\n                <td style="padding: 18px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td style="width: 50%; padding: 0 10px 0 0; vertical-align: bottom;">\n                        <span style="font-size: 12px; font-weight: bold; color: #6b7280; text-transform: uppercase;">[LANG:COM_J2COMMERCE_EMAIL_PACKED_BY]</span>\n                        <div style="margin-top: 8px; border-bottom: 1px solid #d1d5db; min-height: 28px;"></div>\n                      </td>\n                      <td style="width: 25%; padding: 0 10px; vertical-align: bottom;">\n                        <span style="font-size: 12px; font-weight: bold; color: #6b7280; text-transform: uppercase;">[LANG:COM_J2COMMERCE_EMAIL_DATE]</span>\n                        <div style="margin-top: 8px; border-bottom: 1px solid #d1d5db; min-height: 28px;"></div>\n                      </td>\n                      <td style="width: 25%; padding: 0 0 0 10px; vertical-align: bottom;">\n                        <span style="font-size: 12px; font-weight: bold; color: #6b7280; text-transform: uppercase;">[LANG:COM_J2COMMERCE_EMAIL_BOXES]</span>\n                        <div style="margin-top: 8px; border-bottom: 1px solid #d1d5db; min-height: 28px;"></div>\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Footer -->\n        <tr>\n          <td style="padding: 18px 30px; background-color: #ffffff; border-radius: 0 0 12px 12px; border-top: 1px solid #f3f4f6; text-align: center;">\n            <p style="font-size: 12px; color: #9ca3af; margin: 0;">\n              &copy; [CURRENT_YEAR] [SITENAME] &bull; [SITEURL]\n            </p>\n          </td>\n        </tr>\n\n      </table>\n    </td>\n  </tr>\n</table>\n', '', 'visual', '', '', '*', 1, 1),
        (2, 'Invoice', 'invoice', '*', '1', '*', '<!-- J2Commerce Invoice — Modern Template -->\n<style>\n  @media only screen and (max-width: 620px) {\n    .inv-container { width: 100% !important; }\n    .mobile-padding { padding-left: 16px !important; padding-right: 16px !important; }\n    .mobile-full { width: 100% !important; display: block !important; }\n    .address-col { display: block !important; width: 100% !important; padding: 0 0 12px 0 !important; }\n  }\n  @media print {\n    body { margin: 0; padding: 0; }\n    .no-print { display: none !important; }\n  }\n</style>\n\n<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 20px 10px;">\n      <table class="inv-container" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%; background-color: #ffffff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td style="padding: 20px 30px; background-color: #ffffff; border-radius: 12px 12px 0 0; text-align: center;">\n            [IF:STORE_LOGO_URL]\n            <img src="[STORE_LOGO_URL]" alt="[SITENAME]" style="display: block; margin: 0 auto; border: 0; height: [LOGO_MAX_HEIGHT]px; width: auto;" />\n            [/IF:STORE_LOGO_URL]\n            [IFNOT:STORE_LOGO_URL]\n            <span style="font-size: 22px; font-weight: bold; color: [ACCENT_COLOR];">[SITENAME]</span>\n            [/IFNOT:STORE_LOGO_URL]\n          </td>\n        </tr>\n\n        <!-- Invoice Header Banner -->\n        <tr>\n          <td style="background-color: [ACCENT_COLOR]; padding: 28px 30px; text-align: center;">\n            <table cellpadding="0" cellspacing="0" border="0" align="center">\n              <tr>\n                <td style="width: 50px; height: 50px; background-color: rgba(255,255,255,0.2); border-radius: 50%; text-align: center; vertical-align: middle; font-size: 24px; color: #ffffff;">\n                  &#128196;\n                </td>\n              </tr>\n            </table>\n            <h1 style="margin: 14px 0 4px 0; font-size: 24px; font-weight: bold; color: #ffffff; text-transform: uppercase; letter-spacing: 1px;">[SITENAME]</h1>\n            <p style="margin: 0; font-size: 14px; color: rgba(255,255,255,0.85);">\n              [LANG:COM_J2COMMERCE_EMAIL_ORDER_5]\n            </p>\n          </td>\n        </tr>\n\n        <!-- Billing & Shipping Address Cards -->\n        <tr>\n          <td class="mobile-padding" style="padding: 20px 20px 0 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0">\n              <tr>\n                <!-- Bill To -->\n                <td class="address-col" style="width: 50%; vertical-align: top; padding-right: 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_BILL_TO]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 14px; color: #1f2937; line-height: 1.6;">\n                        <strong style="font-size: 15px;">[BILLING_FIRSTNAME] [BILLING_LASTNAME]</strong>\n                        [IF:BILLING_COMPANY]<br />[BILLING_COMPANY][/IF:BILLING_COMPANY]<br />\n                        [BILLING_ADDRESS_1]\n                        [IF:BILLING_ADDRESS_2]<br />[BILLING_ADDRESS_2][/IF:BILLING_ADDRESS_2]<br />\n                        [BILLING_CITY], [BILLING_STATE] [BILLING_ZIP]<br />\n                        [BILLING_COUNTRY]\n                        [IF:BILLING_PHONE]<br />&#128222; [BILLING_PHONE][/IF:BILLING_PHONE]\n                        [IF:BILLING_EMAIL]<br />&#9993; [BILLING_EMAIL][/IF:BILLING_EMAIL]\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n                <!-- Ship To -->\n                <!--[IF:SHIPPING_FIRSTNAME]-->\n                <td class="address-col" style="width: 50%; vertical-align: top; padding-left: 8px;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px;">\n                    <tr>\n                      <td style="padding: 14px 18px; border-bottom: 1px solid #f3f4f6; font-size: 13px; font-weight: bold; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_SHIP_TO]</td>\n                    </tr>\n                    <tr>\n                      <td style="padding: 14px 18px; font-size: 14px; color: #1f2937; line-height: 1.6;">\n                        <strong style="font-size: 15px;">[SHIPPING_FIRSTNAME] [SHIPPING_LASTNAME]</strong>\n                        [IF:SHIPPING_COMPANY]<br />[SHIPPING_COMPANY][/IF:SHIPPING_COMPANY]<br />\n                        [SHIPPING_ADDRESS_1]\n                        [IF:SHIPPING_ADDRESS_2]<br />[SHIPPING_ADDRESS_2][/IF:SHIPPING_ADDRESS_2]<br />\n                        [SHIPPING_CITY], [SHIPPING_STATE] [SHIPPING_ZIP]<br />\n                        [SHIPPING_COUNTRY]\n                        [IF:SHIPPING_PHONE]<br />&#128222; [SHIPPING_PHONE][/IF:SHIPPING_PHONE]\n                      </td>\n                    </tr>\n                  </table>\n                </td>\n                <!--[/IF:SHIPPING_FIRSTNAME]-->\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Items Table WITH Prices -->\n        <tr>\n          <td class="mobile-padding" style="padding: 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 10px; overflow: hidden;">\n              <tr>\n                <td colspan="5" style="padding: 16px 20px; border-bottom: 1px solid #f3f4f6;">\n                  <span style="font-size: 15px; font-weight: bold; color: #1f2937;">[LANG:COM_J2COMMERCE_EMAIL_ORDER_ITEMS]</span>\n                </td>\n              </tr>\n              <tr>\n                <td style="padding: 10px 20px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px;" colspan="2">[LANG:COM_J2COMMERCE_EMAIL_PRODUCT]</td>\n                <td style="padding: 10px 10px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; text-align: center; width: 50px;">[LANG:COM_J2COMMERCE_EMAIL_QTY]</td>\n                <td style="padding: 10px 10px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; text-align: right; width: 80px;">[LANG:COM_J2COMMERCE_EMAIL_PRICE]</td>\n                <td style="padding: 10px 20px; font-size: 11px; font-weight: bold; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; text-align: right; width: 90px;">[LANG:COM_J2COMMERCE_EMAIL_TOTAL]</td>\n              </tr>\n              <!--[ITEMS_LOOP]-->\n              <tr>\n                <td style="padding: 12px 0 12px 20px; border-top: 1px solid #f3f4f6; vertical-align: top; width: 60px;">\n                  [IF:ITEM_IMAGE]\n                  <img src="[ITEM_IMAGE]" alt="[ITEM_NAME]" width="50" height="50" style="border-radius: 6px; object-fit: cover; display: block; border: 1px solid #f3f4f6;" />\n                  [/IF:ITEM_IMAGE]\n                  [IFNOT:ITEM_IMAGE]\n                  <table cellpadding="0" cellspacing="0" border="0"><tr><td style="width: 50px; height: 50px; background-color: #f3f4f6; border-radius: 6px; text-align: center; vertical-align: middle; font-size: 20px; color: #d1d5db;">&#128230;</td></tr></table>\n                  [/IFNOT:ITEM_IMAGE]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; vertical-align: top;">\n                  <span style="font-size: 14px; font-weight: 600; color: #1f2937;">[ITEM_NAME]</span>\n                  [IF:ITEM_SKU]<br /><span style="font-size: 12px; color: #9ca3af;">[LANG:COM_J2COMMERCE_EMAIL_SKU_2]</span>[/IF:ITEM_SKU]\n                  [IF:ITEM_OPTIONS]<br /><span style="font-size: 12px; color: #6b7280;">[ITEM_OPTIONS]</span>[/IF:ITEM_OPTIONS]\n                  [ITEM_ANNOTATIONS]\n                </td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; text-align: center; vertical-align: top; font-size: 14px; color: #1f2937;">[ITEM_QTY]</td>\n                <td style="padding: 12px 10px; border-top: 1px solid #f3f4f6; text-align: right; vertical-align: top; font-size: 14px; color: #1f2937;">[ITEM_PRICE]</td>\n                <td style="padding: 12px 20px; border-top: 1px solid #f3f4f6; text-align: right; vertical-align: top; font-size: 14px; font-weight: 600; color: #1f2937;">[ITEM_TOTAL]</td>\n              </tr>\n              <!--[/ITEMS_LOOP]-->\n\n              <!-- Totals -->\n              <tr>\n                <td colspan="5" style="padding: 0 20px; border-top: 2px solid #e5e7eb;">\n                  <table width="100%" cellpadding="0" cellspacing="0" border="0">\n                    <tr>\n                      <td style="padding: 10px 0; font-size: 13px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_SUBTOTAL]</td>\n                      <td style="padding: 10px 0; font-size: 13px; color: #1f2937; text-align: right;">[SUBTOTAL]</td>\n                    </tr>\n                    <!--[IF:SHIPPING_METHOD]-->\n                    <tr>\n                      <td style="padding: 6px 0; font-size: 13px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_SHIPPING_3]</td>\n                      <td style="padding: 6px 0; font-size: 13px; color: #1f2937; text-align: right;">[SHIPPING_AMOUNT]</td>\n                    </tr>\n                    <!--[/IF:SHIPPING_METHOD]-->\n                    <!--[IF:DISCOUNT_AMOUNT]-->\n                    <tr>\n                      <td style="padding: 6px 0; font-size: 13px; color: #16a34a;">[LANG:COM_J2COMMERCE_EMAIL_DISCOUNT]</td>\n                      <td style="padding: 6px 0; font-size: 13px; color: #16a34a; text-align: right;">-[DISCOUNT_AMOUNT]</td>\n                    </tr>\n                    <!--[/IF:DISCOUNT_AMOUNT]-->\n                    <!--[IF:TAX_AMOUNT]-->\n                    <tr>\n                      <td style="padding: 6px 0; font-size: 13px; color: #6b7280;">[LANG:COM_J2COMMERCE_EMAIL_TAX]</td>\n                      <td style="padding: 6px 0; font-size: 13px; color: #1f2937; text-align: right;">[TAX_AMOUNT]</td>\n                    </tr>\n                    <!--[/IF:TAX_AMOUNT]-->\n                    <tr>\n                      <td style="padding: 14px 0 10px 0; font-size: 16px; font-weight: bold; color: #1f2937; border-top: 1px solid #e5e7eb;">[LANG:COM_J2COMMERCE_EMAIL_TOTAL]</td>\n                      <td style="padding: 14px 0 10px 0; font-size: 16px; font-weight: bold; color: [ACCENT_COLOR]; text-align: right; border-top: 1px solid #e5e7eb;">[ORDERAMOUNT]</td>\n                    </tr>\n                  </table>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n        <!-- Payment Info -->\n        <!--[IF:PAYMENT_METHOD]-->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f9fafb; border: 1px solid #e5e7eb; border-radius: 10px;">\n              <tr>\n                <td style="padding: 14px 18px; font-size: 13px; color: #6b7280;">\n                  <strong>[LANG:COM_J2COMMERCE_EMAIL_PAYMENT_METHOD_2]:</strong> [PAYMENT_METHOD]\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <!--[/IF:PAYMENT_METHOD]-->\n\n        <!-- Customer Note -->\n        <!--[IF:CUSTOMER_NOTE]-->\n        <tr>\n          <td class="mobile-padding" style="padding: 0 20px 16px 20px;">\n            <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px;">\n              <tr>\n                <td style="padding: 14px 18px; font-size: 13px; font-weight: bold; color: #92400e; text-transform: uppercase; letter-spacing: 0.5px;">[LANG:COM_J2COMMERCE_EMAIL_CUSTOMER_NOTE_2]</td>\n              </tr>\n              <tr>\n                <td style="padding: 0 18px 14px 18px; font-size: 14px; color: #78350f; line-height: 1.5;">[CUSTOMER_NOTE]</td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <!--[/IF:CUSTOMER_NOTE]-->\n\n        <!-- Hook: After Invoice Body -->\n        [HOOK:AFTER_INVOICE_BODY]\n\n        <!-- Footer -->\n        <tr>\n          <td style="padding: 18px 30px; background-color: #ffffff; border-radius: 0 0 12px 12px; border-top: 1px solid #f3f4f6; text-align: center;">\n            <p style="font-size: 12px; color: #9ca3af; margin: 0;">\n              &copy; [CURRENT_YEAR] [SITENAME] &bull; [SITEURL]\n            </p>\n          </td>\n        </tr>\n\n      </table>\n    </td>\n  </tr>\n</table>\n', '', 'visual', '', '', '*', 1, 2),
        (3, 'Receipt (Thermal)', 'receipt', '*', '1', '*', '<!-- J2Commerce Receipt — Thermal / POS Template -->\n<style>\n  .thermal-receipt {\n    width: 300px;\n    margin: 0 auto;\n    padding: 12px;\n    font-family: \'Courier New\', Courier, monospace;\n    font-size: 12px;\n    color: #111;\n    background: #fff;\n    line-height: 1.4;\n  }\n  .thermal-receipt .center { text-align: center; }\n  .thermal-receipt .right { text-align: right; }\n  .thermal-receipt .bold { font-weight: bold; }\n  .thermal-receipt .dashed {\n    border: none;\n    border-top: 1px dashed #999;\n    margin: 8px 0;\n  }\n  .thermal-receipt .double-dashed {\n    border: none;\n    border-top: 2px dashed #333;\n    margin: 8px 0;\n  }\n  .thermal-receipt table {\n    width: 100%;\n    border-collapse: collapse;\n  }\n  .thermal-receipt td {\n    padding: 1px 0;\n    vertical-align: top;\n    font-size: 12px;\n  }\n  .thermal-receipt .item-row td {\n    padding: 3px 0;\n  }\n  .thermal-receipt .total-row td {\n    padding: 2px 0;\n  }\n  .thermal-receipt .grand-total td {\n    padding: 4px 0;\n    font-size: 14px;\n    font-weight: bold;\n  }\n  @media print {\n    body { margin: 0; padding: 0; background: #fff; }\n    .thermal-receipt { width: 100%; max-width: 300px; }\n  }\n</style>\n\n<div class="thermal-receipt">\n  <!-- Store Header -->\n  <div class="center bold" style="font-size: 16px; margin-bottom: 2px;">\n    [SITENAME]\n  </div>\n  <div class="center" style="font-size: 11px; color: #555; margin-bottom: 4px;">\n    [SITEURL]\n  </div>\n\n  <hr class="double-dashed" />\n\n  <div class="center bold" style="font-size: 14px; letter-spacing: 2px;">\n    [LANG:COM_J2COMMERCE_EMAIL_RECEIPT_2]\n  </div>\n\n  <hr class="dashed" />\n\n  <!-- Order Info -->\n  <table>\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_ORDER_2]</td>\n      <td class="right bold">[ORDERID]</td>\n    </tr>\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_DATE]</td>\n      <td class="right">[ORDERDATE]</td>\n    </tr>\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_STATUS]</td>\n      <td class="right">[ORDERSTATUS]</td>\n    </tr>\n  </table>\n\n  <hr class="dashed" />\n\n  <!-- Customer -->\n  <div style="font-size: 11px; color: #555; text-transform: uppercase; margin-bottom: 2px;">[LANG:COM_J2COMMERCE_EMAIL_CUSTOMER_3]</div>\n  <div>[BILLING_FIRSTNAME] [BILLING_LASTNAME]</div>\n  [IF:BILLING_EMAIL]\n  <div style="font-size: 11px;">[BILLING_EMAIL]</div>\n  [/IF:BILLING_EMAIL]\n\n  <hr class="double-dashed" />\n\n  <!-- Items -->\n  [ITEMS_LOOP]\n  <table class="item-row">\n    <tr>\n      <td colspan="2" class="bold">[ITEM_NAME]</td>\n    </tr>\n    <!--[IF:ITEM_OPTIONS]-->\n    <tr>\n      <td colspan="2" style="font-size: 11px; color: #555; padding-left: 8px;">[ITEM_OPTIONS]</td>\n    </tr>\n    <!--[/IF:ITEM_OPTIONS]-->\n    <!--[IF:ITEM_ANNOTATIONS]-->\n    <tr>\n      <td colspan="2" style="font-size: 11px; padding-left: 8px;">[ITEM_ANNOTATIONS]</td>\n    </tr>\n    <!--[/IF:ITEM_ANNOTATIONS]-->\n    <tr>\n      <td style="padding-left: 8px;">[ITEM_QTY] x [ITEM_PRICE]</td>\n      <td class="right bold">[ITEM_TOTAL]</td>\n    </tr>\n  </table>\n  <hr class="dashed" />\n  [/ITEMS_LOOP]\n\n  <!-- Totals -->\n  <table class="total-row">\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_SUBTOTAL]</td>\n      <td class="right">[SUBTOTAL]</td>\n    </tr>\n    <!--[IF:SHIPPING_METHOD]-->\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_SHIPPING_3]</td>\n      <td class="right">[SHIPPING_AMOUNT]</td>\n    </tr>\n    <!--[/IF:SHIPPING_METHOD]-->\n    <!--[IF:TAX_AMOUNT]-->\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_TAX]</td>\n      <td class="right">[TAX_AMOUNT]</td>\n    </tr>\n    <!--[/IF:TAX_AMOUNT]-->\n    <!--[IF:DISCOUNT_AMOUNT]-->\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_DISCOUNT]</td>\n      <td class="right">-[DISCOUNT_AMOUNT]</td>\n    </tr>\n    <!--[/IF:DISCOUNT_AMOUNT]-->\n  </table>\n\n  <hr class="double-dashed" />\n\n  <table class="grand-total">\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_TOTAL_2]</td>\n      <td class="right">[ORDERAMOUNT]</td>\n    </tr>\n  </table>\n\n  <hr class="double-dashed" />\n\n  <!-- Payment -->\n  [IF:PAYMENT_METHOD]\n  <table>\n    <tr>\n      <td>[LANG:COM_J2COMMERCE_EMAIL_PAID_VIA]</td>\n      <td class="right">[PAYMENT_METHOD]</td>\n    </tr>\n  </table>\n  <hr class="dashed" />\n  [/IF:PAYMENT_METHOD]\n\n  <!-- Hook -->\n  [HOOK:AFTER_RECEIPT_BODY]\n\n  <!-- Footer -->\n  <div class="center" style="margin-top: 12px; font-size: 13px;">\n    [LANG:COM_J2COMMERCE_EMAIL_THANK_YOU_FOR_PURCHASE]\n  </div>\n  <div class="center" style="margin-top: 8px; font-size: 10px; color: #999;">\n    &copy; [CURRENT_YEAR] [SITENAME]\n  </div>\n</div>\n', '', 'visual', '', '', '*', 1, 3),
        (4, 'Receipt (Full Page)', 'receipt', '*', '1', '*', '<!-- J2Commerce Receipt — Modern Template -->\n<style>\n  @media only screen and (max-width: 620px) {\n    .rcpt-container { width: 100% !important; }\n    .mobile-padding { padding-left: 16px !important; padding-right: 16px !important; }\n  }\n  @media print {\n    body { margin: 0; padding: 0; }\n    .no-print { display: none !important; }\n  }\n</style>\n\n<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; font-family: Arial, Helvetica, sans-serif;">\n  <tr>\n    <td align="center" style="padding: 20px 10px;">\n      <table class="rcpt-container" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; width: 100%; background-color: #ffffff;">\n\n        <!-- Logo Bar -->\n        <tr>\n          <td style="padding: 20px 30px; background-color: #ffffff; border-radius: 12px 12px 0 0; text-align: center;">\n            [IF:STORE_LOGO_URL]\n            <img src="[STORE_LOGO_URL]" alt="[SITENAME]" style="display: block; margin: 0 auto; border: 0; height: [LOGO_MAX_HEIGHT]px; width: auto;" />\n            [/IF:STORE_LOGO_URL]\n            [IFNOT:STORE_LOGO_URL]\n            <span style="font-size: 22px; font-weight: bold; color: [ACCENT_COLOR];">[SITENAME]</span>\n            [/IFNOT:STORE_LOGO_URL]\n          </td>\n        </tr>\n\n        <!-- Receipt Header Banner -->\n        <tr>\n          <td style="background-color: [ACCENT_COLOR]; padding: 28px 30px; text-align: center;">\n            <table cellpadding="0" cellspacing="0" border="0" align="center">\n              <tr>\n                <td style="width: 50px; height: 50px; background-color: rgba(255,255,255,0.2); border-radius: 50%; text-align: center; vertical-align: middle; font-size: 24px; color: #ffffff;">\n                  &#9989;\n                </td>\n              </tr>\n            </table>\n            <h1 style="margin: 14px 0 4px 0; font-size: 24px; font-weight: bol